// DIAGNOSTIC ONLY. The omit mode emits invalid program semantics. NEVER execute its binaries.
// It tests cold-build headroom from eliminating capture-to-argument materialization, not a fix.
import { registerHooks } from 'node:module'
globalThis.__captureAblation = function* (storage, local, context, NativeStorage, NativeType, Constant) {
  if (process.env.SILK_CAPTURE_ABLATION !== 'omit') return yield* NativeStorage.materialize(storage, local)
  const type=storage.fn.localTypes.at(local.ordinal)
  if(type===undefined)throw new Error('[DEBUG-capture-ablation] missing capture type')
  const values=[]
  for(const lane of NativeType.valueLanesFor(context.types,type)) {
    values.push(yield* Constant.nullValue(context.lanePointers.builder,NativeType.laneType(context.types,lane)))
  }
  return values
}
registerHooks({load(url,context,nextLoad){
  const result=nextLoad(url,context)
  if(!url.endsWith('/compiler/dist/NativeEffectOperation.js'))return result
  const source=String(result.source),anchor='yield* NativeStorage.materialize(nativeStorage, operation.effect)'
  if(source.split(anchor).length!==3)throw new Error('[DEBUG-capture-ablation] expected Run and Catch capture sites')
  return {...result,source:source.replaceAll(anchor,
    'yield* globalThis.__captureAblation(nativeStorage, operation.effect, context, NativeStorage, NativeType, Constant)')}
}})

