import { spawnSync } from 'node:child_process'
import { readFileSync, writeFileSync, readdirSync, chmodSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { performance } from 'node:perf_hooks'
import os from 'node:os'
const directory = '/tmp/silk-captures.oUGJGc'
const hash = value => createHash('sha256').update(value).digest('hex')
const env = {...process.env,NODE_DISABLE_COMPILE_CACHE:'1'}
for (const key of ['NODE_OPTIONS','NODE_COMPILE_CACHE','NODE_V8_COVERAGE','SILK_NATIVE_CACHE_DIR']) delete env[key]
const fingerprint = () => {
  const paths=[]
  const visit=path=>{ for(const entry of readdirSync(path,{withFileTypes:true})){const child=path+'/'+entry.name;if(entry.isDirectory())visit(child);else if(/\.(js|ts|silk)$/.test(child))paths.push(child)} }
  for(const path of ['packages/compiler/src','packages/compiler/dist','packages/llvm/src','packages/llvm/dist','compiler/src']) visit(path)
  return hash(paths.sort().map(path=>path+':'+hash(readFileSync(path))).join('\n'))
}
const output={command:'packages/cli/dist/bin.js build-exe compiler/src/main.silk --source-root compiler/src --optimization debug --timings',control:'DIAGNOSTIC ABLATION, NOT AN IMPLEMENTATION: read-only loader replaces RunEffectValue/CatchEffect capture materialization with typed null argument values in omit mode. Outputs are deliberately semantically invalid and never executed. Both modes have identical source/dist and loader; omit output is made non-executable.',node:process.version,cpu:os.cpus()[0]?.model,fingerprint:fingerprint(),samples:[]}
const expectedControlHash=hash(readFileSync('/tmp/silk-captures.oUGJGc/before'))
for(const [index,mode] of ['control','omit','omit','control','control','omit'].entries()){
  const binary=`${directory}/paired-${index}-${mode}-NOT-RUNNABLE`
  const args=['-l',process.execPath,'--import','/tmp/silk-captures.oUGJGc/ablation.mjs','packages/cli/dist/bin.js','build-exe','compiler/src/main.silk','--source-root','compiler/src','--optimization','debug','--output',binary,'--timings']
  const loadBefore=os.loadavg(),start=performance.now()
  const result=spawnSync('/usr/bin/time',args,{env:{...env,SILK_CAPTURE_ABLATION:mode},encoding:'utf8',timeout:180000,maxBuffer:32*1024*1024})
  const wallMs=performance.now()-start
  if(result.status!==0)throw new Error(JSON.stringify(result))
  chmodSync(binary,0o600)
  const binarySha256=hash(readFileSync(binary))
  if(mode==='control'&&binarySha256!==expectedControlHash)throw new Error('Control binary differs from uninstrumented baseline')
  const phases=[...(result.stdout+'\n'+result.stderr).matchAll(/^\s+([\w-]+)\s+([\d.]+)ms\s+(\d+) in \/ (\d+) out\s+(\d+) diag/gm)].map(([,name,wall,inputs,outputs,diagnostics])=>({name,wallMs:Number(wall),inputs:Number(inputs),outputs:Number(outputs),diagnostics:Number(diagnostics)}))
  const times=/([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys/.exec(result.stderr)
  if(!times||!phases.length)throw new Error('Missing timings')
  output.samples.push({index,mode,wallMs,cpuSeconds:Number(times[2])+Number(times[3]),peakRssBytes:Number(/(\d+)\s+maximum resident set size/.exec(result.stderr)?.[1]),phases,loadBefore,loadAfter:os.loadavg(),binarySha256,stdout:result.stdout,stderr:result.stderr})
  writeFileSync(directory+'/paired.json',JSON.stringify(output,null,2)+'\n')
  console.log(`${index+1}/6 ${mode}: ${(wallMs/1000).toFixed(2)}s`)
}
if(fingerprint()!==output.fingerprint)throw new Error('Measured files changed')
output.fingerprintVerified=true
writeFileSync(directory+'/paired.json',JSON.stringify(output,null,2)+'\n')
